import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long n = scanner.nextLong();
        long prev = 1;
        long now = 2;
        int ans = 0;
        while (now <= n) {
            long next = prev + now;
            prev = now;
            now = next;
            ans++;
        }
        System.out.println(ans);
    }
}

